def findMissingAndRepeatedValues(grid):
    # n x n grid, values from 1 to n*n
    n = len(grid)
    max_val = n * n

    # Count occurrence of each number from 1 to n*n
    count = [0] * (max_val + 1)

    for row in grid:
        for val in row:
            count[val] += 1

    repeated = missing = -1

    for num in range(1, max_val + 1):
        if count[num] == 2:
            repeated = num
        elif count[num] == 0:
            missing = num

    return [repeated, missing]
